function logo(id){
 let s;
 if(id==='obsidian')s='<path d="m13 1 8 8-4 15-10-2L3 12 7 6Z" fill="#aa80fa"/><path d="m13 1 1 9-7 12-4-10 4-6Z" fill="#663de0"/><path d="m14 10 7-1-4 15-10-2Z" fill="#b994ff"/><path d="m14 10 3 14-10-2Z" fill="#7954e8"/>';
 else if(id==='linear')s='<circle cx="12" cy="12" r="10" fill="#ddd7ff"/><path d="m3 8 13 13M2 12l10 10M5 4l15 15M9 2l13 13" stroke="#6551e7" stroke-width="1.8"/>';
 else if(id==='onedrive')s='<path d="M6 16a7 7 0 0 1 14-7 5 5 0 0 1 1 10H6Z" fill="#008ded"/><path d="M2 11a5 5 0 0 1 8-1 5 5 0 0 1 3 9H4a4 4 0 0 1-2-8" fill="#32b8ff"/><path d="m9 13 10-4a5 5 0 0 1 2 10H6Z" fill="#0877d5"/>';
 else if(id==='todoist')s='<path d="m3 6 6 3 12-7M3 12l6 3 12-7M3 18l6 3 12-7" fill="none" stroke="white" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>';
 else if(id==='discord')s='<path d="M5 5 9 4l1 2h4l1-2 4 1c3 4 4 8 3 13l-5 2-2-3H9l-2 3-5-2C1 13 2 9 5 5" fill="#edf1ff"/><ellipse cx="8" cy="12" rx="2" ry="2.5" fill="#6256e9"/><ellipse cx="16" cy="12" rx="2" ry="2.5" fill="#6256e9"/>';
 else if(id==='hermes')s='<path d="M3 20V4l9 10 9-10v16M3 4l3 11M21 4l-3 11" fill="none" stroke="#edf3ff" stroke-width="2.3" stroke-linecap="round"/>';
 else if(id==='tailscale')s=Array.from({length:9},(_,k)=>`<circle cx="${5+(k%3)*7}" cy="${5+Math.floor(k/3)*7}" r="2" fill="${k<3?'#72819b':'#d6deee'}"/>`).join('');
 else return `<span class="app-logo ${id}">${icon((tools.find(t=>t.id===id)||{}).icon||'cube')}</span>`;
 return `<span class="app-logo ${id}"><svg viewBox="0 0 24 26" aria-hidden="true">${s}</svg></span>`;
}
