function heading(eyebrow,title,copy,actions=''){return `<section class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(copy)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</section>`;}
function button(label,action,id='',cls='',i=''){return `<button class="button ${cls}" data-action="${action}" data-id="${esc(id)}">${i?icon(i):''}${label}</button>`;}
function panelHead(i,title,sub,action='',label='',id='',tone=''){return `<div class="panel-head"><div class="panel-title"><span class="title-glyph ${tone}">${icon(i)}</span><div><h2>${title}</h2><p>${sub}</p></div></div>${action?button(label,action,id,'small'):''}</div>`;}
const installed=id=>skillStates[id].filter(s=>s==='same'||s==='modified').length;
const machineFor=id=>machines.find(m=>m.id===id);
function meter(name,value,hot=false){return `<span class="micro-meter">${name}<span class="micro-track"><i class="${hot?'hot':''}" style="width:${value}%"></i></span><small>${value}%</small></span>`;}
function miniMachine(m){return `<button class="machine-mini" data-action="machine" data-id="${m.id}" aria-label="Inspect ${m.name}"><span class="machine-mini-header"><span class="os-icon ${m.icon}">${icon(m.icon)}</span><span><h3>${m.name}</h3><span class="address">${m.address}</span></span><span class="circle-chevron">${icon('chevron')}</span></span><span class="online-label"><i class="led"></i>Online</span><span class="machine-tags"><span>${icon('tail')}Tailscale</span><span>${icon('users')}${agents.filter(a=>a.machine===m.id).length} agents</span></span><span class="machine-meters">${meter('CPU',m.cpu,m.id==='worker-01')}${meter('RAM',m.ram)}</span></button>`;}
function workPills(){return `<div class="filter-pills">${[['all','All'],['running','Running'],['idle','Idle'],['blocked','Blocked']].map(([id,label])=>`<button class="${state.workFilter===id?'active':''}" data-action="work-filter" data-id="${id}" aria-pressed="${state.workFilter===id}">${label}<span class="${id==='blocked'?'blocked-count':''}">${id==='all'?agents.length:agents.filter(a=>a.status===id).length}</span></button>`).join('')}</div>`;}
function workRows(){const list=agents.filter(a=>state.workFilter==='all'||a.status===state.workFilter);return `<div class="work-rows">${list.slice(0,5).map((a,k)=>`<button class="work-row" data-action="agent" data-id="${a.id}" aria-label="Inspect ${a.id}: ${esc(a.task)}"><span class="led ${a.status==='blocked'?'red':a.status==='idle'?'idle':''}"></span><span class="agent-icon ${k>1?'teal':''}">${icon(a.machine==='vps-main'?'server':a.machine==='laptop'?'laptop':'monitor')}</span><span class="work-name"><strong>${machineFor(a.machine).name}</strong><small>${a.runtime==='Oh My Pi'?'oh my pi':a.runtime} · ${a.id==='main-agent'?'main':a.id}</small></span><span class="work-task">${esc(a.task)}</span><span class="work-type ${a.phase.toLowerCase()}">${a.phase}</span><span class="work-progress"><i style="width:${a.progress}%"></i></span><time>${a.time}</time><span class="row-more">···</span></button>`).join('')}</div><div class="work-footer"><span>Showing ${Math.min(5,list.length)} of ${list.length} ${state.workFilter==='all'?'':state.workFilter+' '}sessions · simulated</span><button data-action="go" data-id="agents">View all agents →</button></div>`;}
function miniSkills(){return `<div class="skill-mini-wrap"><table class="skill-mini"><thead><tr><th>Agent</th>${skills.slice(0,6).map(s=>`<th>${s.short}</th>`).join('')}</tr></thead><tbody>${miniAgents.map(id=>`<tr><td>${id}</td>${skills.slice(0,6).map((s,k)=>`<td><button data-action="skill" data-id="${id}|${k}" aria-label="${id}, ${s.id}: ${stateNames[skillStates[id][k]]}" title="${s.id} · ${stateNames[skillStates[id][k]]}"><span class="skill-dot ${skillStates[id][k]}"></span></button></td>`).join('')}</tr>`).join('')}</tbody></table></div>${skillLegend()}`;}
function skillLegend(){return `<div class="skill-mini-legend"><span><i class="skill-dot"></i>Installed</span><span><i class="skill-dot modified"></i>Modified</span><span><i class="skill-dot missing"></i>Missing</span><span><i class="skill-dot unassigned"></i>Not assigned</span></div>`;}
function miniTools(){return `<div class="tools-mini">${tools.map(t=>`<button class="tool-mini" data-action="tool" data-id="${t.id}" aria-label="${t.name}: simulated integration">${logo(t.id)}<span><strong>${t.name}</strong><small><i class="led"></i>${t.id==='tailscale'?'4 mock PCs':'Demo ready'}</small></span></button>`).join('')}</div><div class="tools-footer">${button('Add integration','notice','Connections are intentionally unavailable in this public mockup.','', 'plug')}${button('Manage all tools →','go','integrations','text')}</div>`;}
function overview(){return `<section class="hero"><div><h1>Good evening, <span>Michał.</span></h1><p>Your agent ecosystem, in one place. Here’s what matters right now.</p></div><blockquote>“A well-orchestrated mind<br>multiplies itself.”<small>— Your Future Self</small></blockquote></section>
 <section class="metrics" aria-label="Simulated harness summary">
  <article class="metric red"><div class="metric-top"><span class="metric-emblem">${icon('warning')}</span><div><div class="metric-label">Urgent Issues</div><div class="metric-value">2</div><div class="metric-description">1 blocked · 1 config drift</div></div></div><button class="metric-open" data-action="attention" aria-label="Review urgent issues">${icon('chevron')}</button><div class="metric-details"><button data-action="agent" data-id="test-runner"><i class="led red"></i><strong>test-runner</strong><span>Unity license required</span><time>12m ago</time></button><button data-action="go" data-id="settings"><i class="led red"></i><strong>unity-02</strong><span>Skill profile has drifted</span><time>31m ago</time></button></div></article>
  <article class="metric purple"><div class="metric-top"><span class="metric-emblem">${icon('bolt')}</span><div><div class="metric-label">Running Agents</div><div class="metric-value">8 <small>/ 10</small></div><div class="metric-description">agents active</div></div></div><button class="metric-open" data-action="go" data-id="agents" aria-label="View running agents">${icon('chevron')}</button><svg class="agent-spark" viewBox="0 0 240 43" preserveAspectRatio="none" aria-label="Illustrative agent activity"><defs><linearGradient id="sparkfade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#9360ef" stop-opacity=".15"/><stop offset="1" stop-color="#9360ef" stop-opacity="0"/></linearGradient></defs><path d="M1 33C8 23 13 36 22 30S31 12 43 20 51 25 60 15 79 15 91 19 108 26 124 19 147 22 158 24 176 22 184 19 205 9 219 5 233 3 239 1V43H0Z" fill="url(#sparkfade)"/><path d="M1 33C8 23 13 36 22 30S31 12 43 20 51 25 60 15 79 15 91 19 108 26 124 19 147 22 158 24 176 22 184 19 205 9 219 5 233 3 239 1" fill="none" stroke="#a769f6" stroke-width="1.6"/><circle cx="184" cy="19" r="5" fill="#a878ee" opacity=".25"/><circle cx="184" cy="19" r="2.8" fill="#d7afff"/></svg><div class="metric-foot">${icon('up')}+2 from yesterday <span class="sr-only">in this fictional scenario</span></div></article>
  <article class="metric blue"><div class="metric-top"><span class="metric-emblem">${icon('folder')}</span><div><div class="metric-label">Active Projects</div><div class="metric-value">3</div><div class="metric-description">in progress</div></div></div><button class="metric-open" data-action="go" data-id="projects" aria-label="View projects">${icon('chevron')}</button><div class="metric-projects">${projects.map((p,k)=>`<button data-action="project" data-id="${p.id}"><i class="led" style="background:${['#16e2b7','#36cde6','#5694ff'][k]}"></i><strong>${p.name}</strong><span>${p.kind}</span><span>${p.percent}%</span></button>`).join('')}</div></article>
  <article class="metric teal"><div class="metric-top"><span class="metric-emblem">${icon('monitor')}</span><div><div class="metric-label">Machines Online</div><div class="metric-value">4 <small>/ 4</small></div><div class="metric-description">Tailscale connected · demo</div></div></div><button class="metric-open" data-action="go" data-id="machines" aria-label="View machines">${icon('chevron')}</button><div class="equalizer" aria-hidden="true">${[24,31,27,29,34,30,28,33,29,32,26,34,29,30,27,34,29,31].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="metric-foot"><i class="led"></i>All four demo nodes reachable</div></article>
 </section>
 <div class="middle-grid"><section class="panel work-panel"><div class="panel-head"><div class="panel-title"><span class="bolt-glyph">${icon('bolt')}</span><div><h2>Active Work</h2><p>Your agents, tasks and current context</p></div></div>${workPills()}</div>${workRows()}</section>
 <section class="panel focus-panel"><img class="focus-art" src="./assets/focus.webp" alt="" width="234" height="200"><div class="focus-kicker"><span class="mini-icon">${icon('file')}</span>Current Focus</div><div class="focus-name">${logo('obsidian')}<div><h2>Chrono Blade</h2><p>Time-bending action RPG</p></div></div><p class="focus-copy">Building the vertical slice: responsive sword combat, readable enemies and time-manipulation skills.</p><div class="focus-progress" aria-label="68 percent of demo milestones"><span class="track"><i></i></span><strong>68%</strong></div><div class="focus-chips"><button data-action="project" data-id="chrono">${icon('users')}4 agents</button><button data-action="go" data-id="machines">${icon('monitor')}MainPC, worker-01</button><button data-action="tool" data-id="linear">${icon('folder')}Linear</button><button data-action="go" data-id="knowledge">${icon('book')}Obsidian</button></div><div class="focus-actions">${button('View in Linear','notice','Linear is a design placeholder here. No live project is connected.','primary','cube')}${button('View Project','project','chrono','','folder')}</div><div class="focus-vertical">BOLDER<br>AGENTS<br>BIGGER<br>WORLDS</div><div class="focus-quote">“Small agents.<br>Big adventures.”</div></section></div>
 <div class="lower-grid"><section class="panel machines-panel">${panelHead('monitor','Machines','4 machines · Tailscale network','go','Manage','machines')}<div class="machine-minis">${machines.map(miniMachine).join('')}</div></section><section class="panel skill-panel">${panelHead('grid','Skill Matrix','Shared skills across your agents','go','Manage Skills','skills','purple')}${miniSkills()}</section><section class="panel tools-panel">${panelHead('plug','Integrations & Tools','Your connected-tool design inventory','','','','teal')}${miniTools()}</section></div>`;}
function agentsPage(){let list=agents.filter(a=>state.agentFilter==='all'||a.status===state.agentFilter);return heading('RUNTIME / AGENTS','Your team, across machines.','10 fictional agents · 8 running · 1 idle · 1 blocked',button('Compare configurations','go','settings','','swap'))+`<div class="page-toolbar"><div class="note-tabs">${['all','running','idle','blocked'].map(s=>`<button data-action="agent-filter" data-id="${s}" class="${state.agentFilter===s?'active':''}">${s[0].toUpperCase()+s.slice(1)} · ${s==='all'?agents.length:agents.filter(a=>a.status===s).length}</button>`).join('')}</div><span class="eyebrow">SIMULATED INVENTORY</span></div><section class="panel table-scroll"><table class="data-table"><thead><tr><th>Agent</th><th>Status</th><th>Machine</th><th>Runtime / profile</th><th>Skills</th><th>Current task</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td>${a.id}</td><td><span class="state-pill ${a.status}">${a.status}</span></td><td>${machineFor(a.machine).name}</td><td>${a.runtime} / ${a.profile}</td><td>${installed(a.id)}</td><td>${a.task}</td><td>${button('Inspect','agent',a.id,'small','chevron')}</td></tr>`).join('')}</tbody></table></section>`;}
function machinesPage(){return heading('INFRASTRUCTURE / TAILSCALE','One fleet. Every machine.','See the control plane, worker machines and their installed runtimes.',button('Network details','notice','These four addresses and health readings are fictional. No Tailscale API is connected.','','tail'))+`<div class="fleet-grid">${machines.map(m=>`<section class="panel fleet-card"><div class="machine-mini-header"><span class="os-icon ${m.icon}">${icon(m.icon)}</span><div><h3>${m.name}</h3><p class="address">${m.os} · ${m.address}</p></div><span class="state-pill" style="margin-left:auto">Online · demo</span></div><p class="fleet-info"><span>${m.role}</span><span>${agents.filter(a=>a.machine===m.id).length} agents</span></p><div class="focus-chips">${m.tools.map(t=>`<button data-action="notice" data-id="${esc(t+' is represented by sample data, not a connected service.')}">${esc(t)}</button>`).join('')}</div><div class="machine-meters">${meter('CPU',m.cpu,m.id==='worker-01')}${meter('RAM',m.ram)}</div><div class="card-actions">${button('Inspect machine','machine',m.id,'','monitor')}${button('Compare configs','go','settings','','swap')}</div></section>`).join('')}</div>`;}
function projectsPage(){return heading('WORK / PROJECTS','Keep the outcome in focus.','Three sample projects with explicit agent assignments and related context.')+`<div class="project-cards">${projects.map(p=>`<section class="panel project-card"><span class="eyebrow">${p.kind}</span><h2>${p.name}</h2><p>${p.description}</p><div class="track"><i style="width:${p.percent}%"></i></div><small>${p.percent}% · ${p.done}</small><div class="card-actions">${button('View project','project',p.id,'primary','folder')}${button('Notes','go','knowledge','','book')}</div></section>`).join('')}</div>`;}
function skillsPage(){return heading('CAPABILITIES / REGISTRY','Who has what. And what differs.','Compare installed skills, profile drift and missing capabilities.',button('Compare agent settings','go','settings','','swap'))+`<section class="panel"><div class="panel-head"><div class="panel-title"><span class="title-glyph purple">${icon('grid')}</span><div><h2>Skill coverage</h2><p>Select any cell to inspect it or simulate a registry copy.</p></div></div></div><div class="table-scroll"><table class="skill-full"><thead><tr><th>Skill / registry version</th>${miniAgents.map(id=>`<th>${id}</th>`).join('')}</tr></thead><tbody>${skills.map((s,k)=>`<tr><td><strong>${s.id}</strong><small>v${s.version}</small></td>${miniAgents.map(id=>`<td><button data-action="skill" data-id="${id}|${k}" aria-label="${id}, ${s.id}: ${stateNames[skillStates[id][k]]}"><span class="skill-dot ${skillStates[id][k]}"></span></button></td>`).join('')}</tr>`).join('')}</tbody></table></div>${skillLegend()}<p class="skills-explainer">Installed is not a quality score. Modified means local content differs; missing means the profile expects a skill that is absent. “Not assigned” is an intentional difference. Copy operations only change this tab’s demo data.</p></section>`;}
function toolsPage(){return heading('ECOSYSTEM / TOOLS','Specialized tools. One working view.','Every connection below is a placeholder. Nothing exposes your private harness.')+`<div class="integration-cards">${tools.map(t=>`<section class="panel integration-card"><div class="integration-head">${logo(t.id)}<div><h2>${t.name}</h2><small>${t.role}</small></div></div><p>${t.description}</p><small>SIMULATED · NOT CONNECTED</small><div class="card-actions">${button(t.id==='obsidian'?'Explore demo notes':'Inspect integration',t.id==='obsidian'?'go':'tool',t.id==='obsidian'?'knowledge':t.id,'',t.icon)}</div></section>`).join('')}</div>`;}
function filteredNotes(){return notes.filter(n=>(state.noteFilter==='latest'||(state.noteFilter==='important'?n.pinned:n.type==='idea'))&&`${n.title} ${n.body} ${n.folder}`.toLowerCase().includes(state.noteQuery.toLowerCase()));}
function notesList(){return filteredNotes().map(n=>`<article class="note-card"><button class="note-open" data-action="note" data-id="${n.id}"><strong>${esc(n.title)}</strong><p>${esc(n.body.split('\n')[0])}</p><small>${esc(n.folder)} · ${esc(n.time)} · ${n.type}</small></button><button class="pin-button ${n.pinned?'pinned':''}" data-action="pin" data-id="${n.id}" aria-label="${n.pinned?'Unpin':'Pin'} ${esc(n.title)}" aria-pressed="${n.pinned}">${n.pinned?'★':'☆'}</button></article>`).join('')||'<p class="empty-state">No demo notes match your search.</p>';}
function knowledgePage(){return heading('KNOWLEDGE / OBSIDIAN','Your thinking, within reach.','Recent notes, important decisions and ideas—without leaving the dashboard.',button('Capture idea','capture','','primary','bulb'))+`<div class="page-toolbar"><input class="filter-input" id="notes-search" value="${esc(state.noteQuery)}" placeholder="Search demo notes…" aria-label="Search demo notes"><span class="eyebrow">FICTIONAL VAULT / WORK</span></div><div class="notes-grid"><section class="panel"><div class="panel-head"><div class="panel-title"><span class="title-glyph purple">${icon('book')}</span><div><h2>Your notes</h2><p>${notes.length} notes in the demo vault</p></div></div><div class="note-tabs">${[['latest','Latest'],['important','Important'],['ideas','Ideas']].map(([id,label])=>`<button data-action="note-filter" data-id="${id}" class="${state.noteFilter===id?'active':''}">${label}</button>`).join('')}</div></div><div class="note-list" id="notes-list">${notesList()}</div></section><div><section class="panel">${panelHead('pin','Important & pinned','Decisions worth keeping close','','','','purple')}<div class="pinned-list">${notes.filter(n=>n.pinned).map(n=>`<button class="pinned-row" data-action="note" data-id="${n.id}">${icon('file')}${esc(n.title)}</button>`).join('')||'<p class="empty-state">Pin a note to keep it here.</p>'}</div></section><section class="panel capture-card"><span class="eyebrow">QUICK CAPTURE / CTRL I</span><h2>Make room for the next idea.</h2><p>Create a new demo inbox note, or append an idea to an existing project note. Export it as Markdown when you are ready.</p>${button('Add an idea…','capture','','primary','bulb')}<p class="demo-notice">No Obsidian vault is connected. Your changes stay in memory in this tab and disappear on reload.</p></section></div></div>`;}
function activityPage(){return heading('ACTIVITY / ATTENTION','Only the changes that matter.','A simulated timeline of decisions, blocked work and capability changes.')+`<section class="panel"><div class="activity-list">${events.map((e,k)=>`<article class="event-row"><span>${icon(e.icon)}</span><div><h3>${e.title}</h3><p>${e.body}</p>${k<2?`<div class="card-actions">${button('Review',k===0?'agent':'go',k===0?'test-runner':'settings','small')}</div>`:''}</div><time>${e.time}</time></article>`).join('')}</div></section>`;}
function settingsPage(){const l=config(state.left),r=config(state.right);const rows=Object.keys(l);return heading('SETTINGS / CONFIGURATION','Compare the intent, not just the file.','A semantic comparison of two fictional agent profiles.',button('View raw comparison','raw','','','file'))+`<div class="compare-layout"><section class="panel compare-selectors"><h2>Compare agents</h2><label>Source<select id="compare-left">${agents.map(a=>`<option value="${a.id}" ${a.id===state.left?'selected':''}>${a.id} / ${machineFor(a.machine).name}</option>`).join('')}</select></label><label>Target<select id="compare-right">${agents.map(a=>`<option value="${a.id}" ${a.id===state.right?'selected':''}>${a.id} / ${machineFor(a.machine).name}</option>`).join('')}</select></label>${button('Swap sides','swap','','','swap')}<p class="demo-notice">Differences can be intentional. Review the affected settings before applying a simulated copy.</p></section><section class="panel"><div class="panel-head"><div class="panel-title"><span class="title-glyph purple">${icon('swap')}</span><div><h2>Configuration compare</h2><p>${rows.filter(k=>l[k]!==r[k]).length} differences · ${state.left} → ${state.right}</p></div></div></div><div class="table-scroll"><table class="data-table compare-table"><thead><tr><th>Setting</th><th>${state.left}</th><th>${state.right}</th><th>State</th></tr></thead><tbody>${rows.map(k=>`<tr><td>${k}</td><td>${esc(l[k])}</td><td class="${l[k]!==r[k]?'diff':'same'}-value">${esc(r[k])}</td><td>${l[k]!==r[k]?'Different':'Same'}</td></tr>`).join('')}</tbody></table></div><div class="full-panel">${button('Review settings copy','copy-config','','primary','copy')}<p class="demo-notice" style="margin-top:13px">Profile identity, runtime, permissions and skills are not blindly copied. The demo only lets you copy model, reasoning and browser preferences.</p></div></section></div>`;}
const pageRenderers={overview,agents:agentsPage,machines:machinesPage,projects:projectsPage,skills:skillsPage,integrations:toolsPage,activity:activityPage,knowledge:knowledgePage,settings:settingsPage};
function render(){document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.view);if(a.dataset.nav===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=pageRenderers[state.view]();document.title=`HARNESS · ${nav.find(n=>n[0]===state.view)[2]} · Mockup`;}
function go(view){if(!pageRenderers[view])return;closeDialogs();$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');if(location.hash==='#'+view){state.view=view;render();}else location.hash=view;window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1);state.view=pageRenderers[name]?name:'overview';render();$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');});
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function detail(title,kicker,body,actions=''){closeDialogs();$('#detail-content').innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">${esc(kicker)}</span><h2 id="detail-title">${esc(title)}</h2></div><button class="icon-button close-dialog" data-close="detail-dialog" aria-label="Close inspector">×</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;$('#detail-dialog').showModal();}
function detailsGrid(obj){return `<div class="detail-grid">${Object.entries(obj).map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`;}
function inspectAgent(id){const a=agents.find(a=>a.id===id);if(!a)return;detail(a.id,'AGENT / SIMULATED SESSION',`<p>${esc(a.task)}</p>${detailsGrid({Status:a.status,Machine:machineFor(a.machine).name,Runtime:a.runtime,Profile:a.profile,'Installed skills':installed(a.id),Project:projects.find(p=>p.id===a.project).name})}<p class="demo-notice">This is a fictional agent session. There is no connection to a process, terminal or private machine.</p>`,button('Compare settings','compare-agent',id,'','swap')+button('Open in HERDR','notice','HERDR is not connected in this public design mockup.','','branch'));}
function inspectMachine(id){const m=machineFor(id);if(!m)return;detail(m.name,'MACHINE / DEMO INVENTORY',`<p>${m.role}</p>${detailsGrid({'Operating system':m.os,'Example tailnet address':m.address,CPU:m.cpu+'%',RAM:m.ram+'%','Installed tools':m.tools.join(', '),'Assigned agents':agents.filter(a=>a.machine===m.id).map(a=>a.id).join(', ')})}<p class="demo-notice">Example addresses and telemetry only. No live network checks or remote actions are performed.</p>`,button('View agents','go','agents','','users'));}
function inspectProject(id){const p=projects.find(p=>p.id===id);if(!p)return;detail(p.name,'PROJECT / SAMPLE WORK',`<p>${p.description}</p>${detailsGrid({Progress:p.percent+'% of fictional milestones',Checklist:p.done,Agents:agents.filter(a=>a.project===p.id).map(a=>a.id).join(', '),Context:p.id==='chrono'?'Combat readability · Unity workflow':'Control plane principles'})}<p class="demo-notice">Milestones and activity are sample data, not a statement about your actual project progress.</p>`,button('Related notes','go','knowledge','','book')+button('View agents','go','agents','','users'));}
function inspectTool(id){const t=tools.find(t=>t.id===id);if(!t)return;detail(t.name,'INTEGRATION / DESIGN PLACEHOLDER',`<div class="integration-head">${logo(t.id)}<strong>${t.role}</strong></div><p style="margin-top:16px">${t.description}</p><p class="demo-notice">Not connected. No credentials, private configuration, vault content or live API access are included in this public repository.</p>`,t.id==='obsidian'?button('Explore notes','go','knowledge','primary','book'):button('View all tools','go','integrations','','plug'));}
function inspectSkill(value){const [id,kText]=value.split('|'),k=Number(kText),s=skills[k];if(!s||!skillStates[id])return;const status=skillStates[id][k];detail(s.id,'SKILL / COMPARE & COPY',`<p>${esc(id)} · ${stateNames[status]}</p>${detailsGrid({Registry:'v'+s.version,Agent:id,Installation:stateNames[status],'Operation scope':'This browser tab only'})}<p>${status==='modified'?'This fixture represents a local change. A real adapter would show the exact file diff before any overwrite.':status==='missing'?'The sample profile expects this skill, but the agent does not have it installed.':status==='unassigned'?'This skill is not assigned to the sample profile. Different capabilities can be intentional.':'The sample installation matches its registry version.'}</p><p class="demo-notice">“Copy registry version” changes this demo cell only. It does not copy any file or affect a real agent.</p>`,button('Cancel','close','','','')+button('Copy registry version','apply-skill',value,'primary','copy'));}
function inspectNote(id){const n=notes.find(n=>n.id===id);if(!n)return;detail(n.title,'OBSIDIAN / DEMO NOTE',`<p>${esc(n.folder)} · ${esc(n.time)}${n.pinned?' · Important':''}</p><div class="note-preview-text">${esc(n.body)}</div>`,button(n.pinned?'Unpin note':'Pin note','pin-detail',id,'','pin')+button('Export .md','export-note',id,'','download')+(['combat','harness'].includes(n.id)?button('Append idea','capture',n.id,'primary','bulb'):''));}
function attention(){detail('Two decisions need you.','ATTENTION / FICTIONAL SCENARIO',`<div class="activity-list">${events.slice(0,2).map(e=>`<article class="event-row"><span>${icon(e.icon)}</span><div><h3>${e.title}</h3><p>${e.body}</p></div><time>${e.time}</time></article>`).join('')}</div>`,button('Review activity','go','activity','primary','clock'));}
function openIdea(target='new'){closeDialogs();$('#idea-form').reset();$('#idea-target').value=['harness','combat'].includes(target)?target:'new';$('#idea-dialog').showModal();$('#idea-title').focus();}
function exportNote(id){const n=notes.find(n=>n.id===id);if(!n)return;const blob=new Blob([`# ${n.title}\n\n> Exported from the HARNESS mockup. Not synced to Obsidian.\n\n${n.body}\n`],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=n.title.replace(/[^a-z0-9 -]/gi,'').slice(0,70)+'.md';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function configCopyReview(){const l=config(state.left),r=config(state.right);const sameRuntime=l.Runtime===r.Runtime;detail('Review settings copy','CONFIGURATION / EXPLICIT DEMO ACTION',`<p>From <strong>${esc(state.left)}</strong> to <strong>${esc(state.right)}</strong>.</p><pre class="code-preview">${esc(['Model','Reasoning','Browser'].map(k=>`${k}: ${r[k]} → ${l[k]}`).join('\n'))}</pre><p>${sameRuntime?'Compatible runtime in this fictional example.':'The runtimes differ. Cross-runtime copying is intentionally disabled in this demo.'}</p><p class="demo-notice">Only the three preferences shown above can be copied. Runtime, profile identity, permissions, hooks and skill files are untouched. No real configuration is written.</p>`,button('Cancel','close')+(sameRuntime&&state.left!==state.right?button('Apply to demo','apply-config','','primary','check'):''));}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
const actions={
 go,agent:inspectAgent,machine:inspectMachine,project:inspectProject,tool:inspectTool,skill:inspectSkill,note:inspectNote,attention,capture:openIdea,notice:toast,close:closeDialogs,
 'work-filter':id=>{state.workFilter=id;render();},'agent-filter':id=>{state.agentFilter=id;render();},'note-filter':id=>{state.noteFilter=id;render();},
 pin:id=>{const n=notes.find(n=>n.id===id);if(n){n.pinned=!n.pinned;render();}},
 'pin-detail':id=>{const n=notes.find(n=>n.id===id);if(n){n.pinned=!n.pinned;render();inspectNote(id);}},
 'export-note':exportNote,
 'compare-agent':id=>{state.right=id;go('settings');},
 'apply-skill':value=>{const [id,k]=value.split('|');if(skillStates[id]&&skills[Number(k)]){skillStates[id][Number(k)]='same';closeDialogs();render();toast('Registry version copied to the demo cell. No agent files changed.');}},
 swap:()=>{[state.left,state.right]=[state.right,state.left];render();},
 raw:()=>detail('Raw configuration comparison','CONFIGURATION / DEMO JSON',`<pre class="code-preview">${esc(JSON.stringify({source:{agent:state.left,settings:config(state.left)},target:{agent:state.right,settings:config(state.right)}},null,2))}</pre>`),
 'copy-config':configCopyReview,
 'apply-config':()=>{const src=config(state.left),dst=config(state.right);if(src.Runtime!==dst.Runtime)return;configOverrides[state.right]={...configOverrides[state.right],Model:src.Model,Reasoning:src.Reasoning,Browser:src.Browser};closeDialogs();render();toast('Three preferences updated in the demo only. No configuration files were written.');}
};
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close)?.close();return;}const el=e.target.closest('[data-action]');if(el&&actions[el.dataset.action])actions[el.dataset.action](el.dataset.id||'');});
document.addEventListener('change',e=>{if(e.target.id==='compare-left'){state.left=e.target.value;render();}if(e.target.id==='compare-right'){state.right=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='notes-search'){state.noteQuery=e.target.value;$('#notes-list').innerHTML=notesList();}});
$('#idea-form').addEventListener('submit',e=>{e.preventDefault();const title=$('#idea-title').value.trim(),body=$('#idea-body').value.trim();if(!title||!body)return;const target=$('#idea-target').value;const existing=notes.find(n=>n.id===target);if(existing){existing.body+='\n\n## '+title+'\n\n'+body;existing.time='Just now';notes=[existing,...notes.filter(n=>n!==existing)];state.noteFilter='latest';}else{notes.unshift({id:'idea-'+Date.now(),title,body,folder:'00 Inbox',time:'Just now',pinned:false,type:'idea'});state.noteFilter='ideas';}state.noteQuery='';go('knowledge');toast(existing?'Idea appended to the demo note. Nothing was written to Obsidian.':'Idea added to this tab’s demo notes. Export it before reloading.');});
$('#capture-trigger').addEventListener('click',()=>openIdea());$('#notifications').addEventListener('click',attention);
$('#atmosphere').addEventListener('click',()=>{const on=document.body.classList.toggle('calm');$('#atmosphere').setAttribute('aria-pressed',String(on));$('#atmosphere').setAttribute('aria-label',on?'Restore decorative glow':'Reduce decorative glow');});
$('#menu-button').addEventListener('click',()=>{const on=$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(on));});
document.addEventListener('click',e=>{if(innerWidth<=480&&$('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar,#menu-button')){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}});
let commandItems=[];
function commandEntries(){return [...projects.map(p=>({label:p.name,kind:'Project',icon:'folder',action:'project',id:p.id})),...tools.map(t=>({label:t.name,kind:'Tool / '+t.role,icon:t.icon,action:'tool',id:t.id})),...nav.map(([id,i,label])=>({label,kind:'View',icon:i,action:'go',id})),{label:'Capture an idea',kind:'Obsidian · demo',icon:'bulb',action:'capture',id:''},...agents.map(a=>({label:a.id,kind:machineFor(a.machine).name+' / '+a.runtime,icon:'cube',action:'agent',id:a.id})),...machines.map(m=>({label:m.name,kind:'Machine',icon:m.icon,action:'machine',id:m.id})),...notes.map(n=>({label:n.title,kind:'Note / '+n.folder,icon:'book',action:'note',id:n.id})),...skills.map((s,k)=>({label:s.id,kind:'Skill registry',icon:'skill',action:'skill',id:'unity-01|'+k}))];}
function renderCommands(){const q=$('#command-input').value.trim().toLowerCase();const entries=commandEntries();commandItems=(q?entries.filter(x=>(x.label+' '+x.kind).toLowerCase().includes(q)):entries.filter(x=>x.kind==='View'||x.action==='capture')).slice(0,q?15:10);state.commandIndex=Math.min(state.commandIndex,Math.max(0,commandItems.length-1));$('#command-results').innerHTML=commandItems.map((x,k)=>`<button class="command-result ${k===state.commandIndex?'active':''}" data-command-index="${k}">${icon(x.icon)}<span>${esc(x.label)}</span><small>${esc(x.kind)}</small></button>`).join('')||'<p class="empty-state">No matching demo records.</p>';}
function openCommands(){closeDialogs();$('#command-input').value='';state.commandIndex=0;renderCommands();$('#command-dialog').showModal();$('#command-input').focus();}
function runCommand(k){const entry=commandItems[k];if(!entry)return;$('#command-dialog').close();actions[entry.action](entry.id);}
$('#search-trigger').addEventListener('click',openCommands);$('#command-input').addEventListener('input',()=>{state.commandIndex=0;renderCommands();});
$('#command-results').addEventListener('click',e=>{const b=e.target.closest('[data-command-index]');if(b)runCommand(Number(b.dataset.commandIndex));});
$('#command-input').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const length=commandItems.length||1;state.commandIndex=(state.commandIndex+(e.key==='ArrowDown'?1:-1)+length)%length;renderCommands();$('#command-results .active')?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'){e.preventDefault();runCommand(state.commandIndex);}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommands();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='i'){e.preventDefault();openIdea();}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}});
for(const d of document.querySelectorAll('dialog')){d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});}
state.view=pageRenderers[location.hash.slice(1)]?location.hash.slice(1):'overview';render();
